import type { LanguageCode } from '@maw/content-sdk';
import { articlesPagination } from '../../../_lib/articles-pagination';

export type ArticlesPageStaticParam = {
  locale: string;
  page: string;
};

/** Minimal listing dependency needed to build archive static params. */
export interface ArticleCountService {
  listAll(options: { lang: LanguageCode }): Promise<ReadonlyArray<unknown>>;
}

/**
 * Builds the `(locale, page)` pairs for every archive page after the first.
 * Page 1 lives at `/articles` and is generated by its own route. Extracted so
 * the per-locale iteration is independently testable (`generateStaticParams` is
 * not exported for unit testing).
 */
export async function buildArticlesPageStaticParams(
  locales: readonly string[],
  articleService: ArticleCountService,
): Promise<ArticlesPageStaticParam[]> {
  const perLocale = await Promise.all(
    locales.map(async (locale) => {
      const articles = await articleService.listAll({
        lang: locale as LanguageCode,
      });
      const pageCount = articlesPagination.getPageCount(articles.length);

      return Array.from({ length: Math.max(0, pageCount - 1) }, (_, index) => ({
        locale,
        page: String(index + 2),
      }));
    }),
  );

  return perLocale.flat();
}
